import { workflow, node, trigger, ifElse, expr } from '@n8n/workflow-sdk';

// 21 - NOYA Creative Concepts (Adam, 7 Oct 2026). For media, podcast, YouTube, publication, creator and production targets:
// CONCEPT (what could be filmed), BACKDROP (Pyramids, Mena House, Grand Egyptian Museum, Nile, Aswan, El Gouna, Red Sea, desert,
// villas), NOYA ROLE and COMMERCIAL VALUE, from the stored evidence only. One Flash-Lite call per target, deterministic check,
// budget guardrail first. The planner adds the concept to the draft angle. Generated by n8n/build_w20_22.py.

const manualRun = trigger({ type: 'n8n-nodes-base.manualTrigger', version: 1, config: { name: 'Manual Run' } });
const schedule = trigger({ type: 'n8n-nodes-base.scheduleTrigger', version: 1.2, config: { name: "Daily 11:30 Cairo", parameters: { rule: { interval: [{ field: 'cronExpression', expression: "30 11 * * *" }] } } } });
const budget = node({ type: 'n8n-nodes-base.httpRequest', version: 4.2, config: { name: "AI Budget Check", retryOnFail: true, maxTries: 3, waitBetweenTries: 2000,
  parameters: { method: 'POST', url: 'https://gagbhykzmtstekpqujyl.supabase.co/rest/v1/rpc/ai_budget_status', authentication: 'predefinedCredentialType', nodeCredentialType: 'supabaseApi',
    sendBody: true, contentType: 'json', specifyBody: 'json', jsonBody: expr("{{ \"{}\" }}"), options: { timeout: 60000 } },
  credentials: { supabaseApi: { id: 'EkLYXHBGqNUjAGKP', name: 'Supabase account' } } } });
const budgetOk = ifElse({ version: 2.2, config: { name: "Budget OK?", parameters: { conditions: { options: { caseSensitive: true, leftValue: '', typeValidation: 'loose' },
  conditions: [{ leftValue: expr("{{ [\"OK\", \"OVER_TARGET\"].includes($json.status) }}"), operator: { type: 'boolean', operation: 'true', singleValue: true } }], combinator: 'and' } } } });
const queue = node({ type: 'n8n-nodes-base.httpRequest', version: 4.2, config: { name: "Concept Queue", retryOnFail: true, maxTries: 3, waitBetweenTries: 2000,
  parameters: { method: 'POST', url: 'https://gagbhykzmtstekpqujyl.supabase.co/rest/v1/rpc/creative_concept_queue', authentication: 'predefinedCredentialType', nodeCredentialType: 'supabaseApi',
    sendBody: true, contentType: 'json', specifyBody: 'json', jsonBody: expr("{{ JSON.stringify({ p_limit: 8 }) }}"), options: { timeout: 60000 } },
  credentials: { supabaseApi: { id: 'EkLYXHBGqNUjAGKP', name: 'Supabase account' } } } });
const prompts = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: "Build Prompts", parameters: { mode: 'runOnceForAllItems', jsCode: "// One filmable concept per media / podcast / creator target (Adam, 7 Oct 2026): what could be filmed, where, what NOYA\n// arranges, and why it helps NOYA. Uses only the stored evidence about the company; never invents audiences or facts.\nvar items = ($input.first().json.items) || [];\nvar BACKDROPS = ['Pyramids of Giza', 'Mena House', 'Grand Egyptian Museum', 'The Nile', 'Aswan', 'Luxor', 'El Gouna', 'Red Sea', 'Western Desert', 'Cairo', 'Private villa or resort'];\nvar SYSTEM = [\n  'You propose ONE filmable concept in Egypt for a media company, podcast, YouTube show, publication, creator or production company.',\n  'Rules: use ONLY the facts in EVIDENCE about the company. Never invent audience size, episode names, awards, people, dates or past work.',\n  'concept: one or two sentences describing what could actually be filmed, fitted to what the company does (a conversation, an episode, a feature, a series segment).',\n  'backdrop: choose exactly one from the list.',\n  'noya_role: what NOYA would arrange (location access, permits, hotel, transport, hospitality, itinerary, local production), one sentence.',\n  'commercial_value: why this helps NOYA commercially (visibility with their audience, content NOYA can reuse, a relationship), one sentence, no claims about numbers.',\n  'Plain British English, understated, no superlatives. Return JSON only.'\n].join('\\n');\nreturn items.map(function (it) {\n  var user = ['COMPANY: ' + it.company + (it.country ? ' (' + it.country + ')' : '') + (it.company_type ? ', ' + it.company_type : ''),\n              'EVIDENCE: ' + (it.evidence || ''), 'BACKDROPS: ' + BACKDROPS.join('; ')].join('\\n');\n  return { json: Object.assign({}, it, { backdrops: BACKDROPS, request: {\n    systemInstruction: { parts: [{ text: SYSTEM }] },\n    contents: [{ role: 'user', parts: [{ text: user }] }],\n    generationConfig: { temperature: 0.5, maxOutputTokens: 400, responseMimeType: 'application/json',\n      responseSchema: { type: 'OBJECT', properties: { concept: { type: 'STRING' }, backdrop: { type: 'STRING', enum: BACKDROPS },\n        noya_role: { type: 'STRING' }, commercial_value: { type: 'STRING' } }, required: ['concept', 'backdrop', 'noya_role', 'commercial_value'] } } } }) };\n});\n" } } });
const gemini = node({ type: 'n8n-nodes-base.httpRequest', version: 4.2, config: { name: 'Flash-Lite Concept', onError: 'continueRegularOutput', retryOnFail: true, maxTries: 2, waitBetweenTries: 5000,
  parameters: { method: 'POST', url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent',
    authentication: 'predefinedCredentialType', nodeCredentialType: 'googlePalmApi', sendBody: true, contentType: 'json', specifyBody: 'json',
    jsonBody: expr('{{ JSON.stringify($json.request) }}'), options: { timeout: 30000, batching: { batch: { batchSize: 1, batchInterval: 4000 } } } },
  credentials: { googlePalmApi: { id: 'tqsVAbFrBUJsN3Y0', name: 'Google Gemini(PaLM) Api account' } } } });
const verify = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: "Verify Concept", parameters: { mode: 'runOnceForAllItems', jsCode: "// Deterministic check: the backdrop must be one of the list, and every capitalised word or number in the concept must come\n// from the evidence, the backdrop list or plain Egypt geography. Anything else is dropped, not saved.\nvar src = $('Build Prompts').all(0);\nvar ALLOWED = ('noya egypt egyptian cairo giza pyramids pyramid mena house grand museum gem nile aswan luxor el gouna red sea western desert white ' +\n  'sahara siwa sinai upper private villa resort i a an the in at on from with for of and or this their its it we our').split(' ');\nfunction inText(t, w) { return new RegExp('(^|[^a-z0-9])' + w.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&') + '([^a-z0-9]|$)').test(t); }\nreturn $input.all().map(function (x, i) {\n  var it = src[i].json, r = x.json || {};\n  var err = r.error ? (typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error))) : '';\n  var u = r.usageMetadata || {};\n  var text = ''; try { text = (r.candidates[0].content.parts || []).map(function (p) { return p.text || ''; }).join(''); } catch (e) { text = ''; }\n  var o = {}; try { o = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1)); } catch (e) { o = {}; }\n  var corpus = (it.company + ' ' + (it.company_type || '') + ' ' + (it.country || '') + ' ' + (it.evidence || '')).toLowerCase();\n  var bad = [];\n  (String(o.concept || '') + ' ' + String(o.commercial_value || '')).split(/(?<=[.?!])\\s+/).forEach(function (sent) {\n    (sent.match(/[A-Za-z][A-Za-z0-9'\u2019&-]*/g) || []).forEach(function (w, k) {\n      if (!/^[A-Z]/.test(w)) return;\n      var b = w.toLowerCase().replace(/['\u2019]s$/, '');\n      if (ALLOWED.indexOf(b) >= 0 || inText(corpus, b) || (k === 0)) return;\n      if (bad.indexOf(w) < 0) bad.push(w);\n    });\n  });\n  ((String(o.concept || '') + ' ' + String(o.commercial_value || '')).match(/\\d[\\d,.]*/g) || []).forEach(function (n) { if (corpus.indexOf(n) < 0) bad.push(n); });\n  var ok = !err && o.concept && it.backdrops.indexOf(o.backdrop) >= 0 && bad.length === 0;\n  var rl = /429|too many requests|resource[_ ]exhausted|quota|rate limit/i.test(err);\n  return { json: { ok: ok, company: it.company, unsupported: bad, error: err.slice(0, 160), p: { company_id: it.company_id, contact_id: it.contact_id || '',\n    concept: ok ? o.concept : '', backdrop: o.backdrop || '', noya_role: o.noya_role || '', commercial_value: o.commercial_value || '',\n    model: 'gemini-3.1-flash-lite',\n    usage: [{ model: 'models/gemini-3.1-flash-lite', input_tokens: u.promptTokenCount || 0, output_tokens: u.candidatesTokenCount || 0,\n              thinking_tokens: u.thoughtsTokenCount || 0, status: err ? (rl ? 'RATE_LIMITED' : 'ERROR') : 'OK' }] } } };\n});\n" } } });
const save = node({ type: 'n8n-nodes-base.httpRequest', version: 4.2, config: { name: "Save Concept", retryOnFail: true, maxTries: 3, waitBetweenTries: 2000, onError: 'continueRegularOutput',
  parameters: { method: 'POST', url: 'https://gagbhykzmtstekpqujyl.supabase.co/rest/v1/rpc/creative_concept_save', authentication: 'predefinedCredentialType', nodeCredentialType: 'supabaseApi',
    sendBody: true, contentType: 'json', specifyBody: 'json', jsonBody: expr("{{ JSON.stringify({ p: $json.p }) }}"), options: { timeout: 60000 } },
  credentials: { supabaseApi: { id: 'EkLYXHBGqNUjAGKP', name: 'Supabase account' } } } });

export default workflow('noya-21-creative-concepts', '21 - NOYA Creative Concepts v1')
  .add(manualRun)
  .to(budget)
  .add(schedule)
  .to(budget)
  .add(budget)
  .to(budgetOk.onTrue(queue.to(prompts.to(gemini.to(verify.to(save))))));
